(async()=>{
 const C=FullTestCore,$=id=>document.getElementById(id),storage=localStorage;
 let set,frames=[],ready=new Set(),active=0,current=1,started=false,done=false,last=0,timer,savePending=false;
 const loading=$('full-loading');
 const api=i=>frames[i]?.contentWindow?.IELTSExam;
 const answerArrays=()=>frames.map((f,i)=>api(i)?.values()||Array(set.items[i].count).fill(''));
 const remaining=()=>Math.max(0,set.remainingMs-(started&&!done?Date.now()-last:0));
 function persist(){if(!started||done)return;set.remainingMs=remaining();last=Date.now();set.active=active;set.current=current;set.snapshots=frames.map((f,i)=>api(i)?.snapshot());try{storage.setItem(C.key,JSON.stringify(set))}catch{}}
 function scheduleSave(){if(savePending)return;savePending=true;queueMicrotask(()=>{savePending=false;persist();paint()})}
 // Use the same footer DOM and shared CSS as single-passage exams.
 function paint(){if(!set||ready.size!==3)return;const values=answerArrays(),row=$('full-footer');const focused=document.activeElement?.dataset?.examQ;row.replaceChildren();
  set.items.forEach((item,i)=>{const p=document.createElement('div');p.className='bb-part bb-clickable'+(i===active?' bb-active-part':'');p.dataset.part=i+1;const allAnswered=values[i].every(Boolean);p.classList.toggle('exam-all-answered',allAnswered);p.tabIndex=0;p.setAttribute('role','button');p.setAttribute('aria-label','Part '+(i+1));p.setAttribute('aria-current',String(i===active));p.onclick=e=>{if(e.target.closest('#bb-dots'))return;switchPart(i)};p.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target===p){e.preventDefault();switchPart(i)}};
   const strip=document.createElement('div');strip.className='exam-part-progress';values[i].forEach((v,j)=>{const seg=document.createElement('span');seg.dataset.progressQ=(i===0?1:i===1?14:27)+j;if(v)seg.className='done';strip.append(seg)});p.append(strip);
   if(i===active){const numbers=document.createElement('div');numbers.className='bb-numbers-row';const label=document.createElement('span');label.className='exam-part-label';label.textContent='Part '+(i+1);if(allAnswered){const check=document.createElement('span');check.className='exam-part-complete';check.textContent='✓';check.setAttribute('aria-label','All questions answered');label.prepend(check)}numbers.append(label);const dots=document.createElement('div');dots.id='bb-dots';dots.className='full-dots';(api(i).footerGroups?.()||values[i].map((_,j)=>[(i===0?1:i===1?14:27)+j])).forEach(ns=>{const n=ns[0],b=document.createElement('button');b.type='button';b.textContent=ns.length>1?n+'–'+ns.at(-1):n;b.dataset.examQ=n;b.dataset.examQuestions=ns.join(',');b.className='video-plain-dot';b.setAttribute('aria-label','Question '+n);b.classList.toggle('answered',ns.some(q=>!!values[i][q-(i===0?1:i===1?14:27)]));b.classList.toggle('video-current',ns.includes(current));b.onclick=e=>{e.stopPropagation();navigate(n)};dots.append(b)});numbers.append(dots);p.append(numbers)}else{const view=document.createElement('div');view.className='bb-inactive-view';const label=document.createElement('span');label.className='bb-inactive-label';label.textContent='Part '+(i+1);const count=document.createElement('span');count.className='bb-inactive-progress';count.textContent=values[i].filter(Boolean).length+' of '+item.count;if(allAnswered){const check=document.createElement('span');check.className='exam-part-complete';check.textContent='✓';check.setAttribute('aria-label','All questions answered');label.prepend(check)}view.append(label);if(!allAnswered)view.append(count);p.append(view)}row.append(p)
  });const b=document.createElement('button');b.className='exam-submit full-submit';b.innerHTML='<svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true" focusable="false"><path d="M3 10l4 4L17 4" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="butt" stroke-linejoin="miter"/></svg>';b.setAttribute('aria-label',done?'Đã nộp bài':'Nộp bài');b.title=done?'Đã nộp bài':'Nộp bài';b.disabled=done;b.onclick=()=>submit(false);row.append(b);$('full-prev').disabled=current<=1;$('full-next').disabled=done;$('full-next').style.visibility='visible';if(focused)row.querySelector('[data-exam-q="'+focused+'"]')?.focus({preventScroll:true});
 }
 function switchPart(i){active=i;frames.forEach((f,j)=>f.hidden=j!==i);current=i===0?1:i===1?14:27;$('full-part').textContent='Part '+(i+1);$('full-rubric').textContent='Read the text and answer questions '+current+'–'+(i===0?13:i===1?26:40)+'.';paint();persist();frames[i].contentWindow.dispatchEvent(new Event('resize'))}
 function navigate(n){if(n<1||n>40)return;const i=n<=13?0:n<=26?1:2;if(i!==active)switchPart(i);n=(api(i).footerGroups?.().find(ns=>ns.includes(n))||[n])[0];current=n;api(i).navigate(n);paint();persist()}
 function tick(){if(!started||done)return;const ms=remaining(),seconds=Math.ceil(ms/1000);$('full-timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('full-timer').classList.toggle('urgent',seconds<=300);if(ms===0)submit(true);else persist()}
 async function submit(automatic){if(done||!started)return;if(!automatic){const approved=window.IELTSConfirmSubmit?await window.IELTSConfirmSubmit({parts:answerArrays().map((v,i)=>({part:i+1,total:set.items[i].count,answered:v.filter(Boolean).length}))}):confirm('Nộp toàn bộ 40 câu và kết thúc bài thi?');if(!approved||done)return;}if(automatic)window.IELTSConfirmSubmit?.close(false);const answers=answerArrays();persist();try{C.submit(storage,set,answers,automatic)}catch{alert('Không thể lưu trạng thái trên trình duyệt này. Hãy cho phép lưu dữ liệu rồi nộp lại.');return}done=true;clearInterval(timer);frames.forEach((f,i)=>api(i).finishFull());$('full-timer').textContent=automatic?'00:00':$('full-timer').textContent;$('full-summary-title').textContent=automatic?'Hết giờ — Đã tự nộp bài':'Đã nộp bài';$('full-summary-text').textContent='Đã trả lời '+answers.flat().filter(Boolean).length+'/40 câu. Passage trả lời từ 6 câu trở lên được đánh dấu đã làm.';$('full-summary').hidden=false;$('full-review').focus();paint()}
 function fail(){if(started)return;$('full-load-error').hidden=false;loading.querySelector('.full-spinner').hidden=true;loading.querySelector('h1').textContent='Không thể mở bộ đề';loading.querySelector('.full-loader-content>p').hidden=true;frames.forEach(f=>f.remove());frames=[];clearTimeout(loadTimeout)}
 const loadTimeout=setTimeout(fail,45000);
 const notesToggle=document.querySelector('.nav-icons svg:last-child');if(notesToggle){notesToggle.setAttribute('role','button');notesToggle.setAttribute('aria-label','Notes');notesToggle.tabIndex=0;const toggle=()=>frames[active]?.contentDocument?.querySelector('.nav-icons svg:last-child')?.dispatchEvent(new frames[active].contentWindow.MouseEvent('click'));notesToggle.onclick=toggle;notesToggle.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}}}
 const headerIcons=[...document.querySelectorAll('.nav-icons>svg,.nav-icons>img')];if(headerIcons.length>4)headerIcons[3].classList.add('exam-chat-icon');const noteIcon=headerIcons.at(-1);if(noteIcon){noteIcon.setAttribute('role','button');noteIcon.setAttribute('aria-label','Notes');noteIcon.tabIndex=0;noteIcon.onclick=()=>frames[active]?.contentWindow?.IELTSAnnotations?.toggle();noteIcon.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();noteIcon.click()}}}
 $('full-retry').onclick=()=>location.reload();$('full-review').onclick=()=>{$('full-summary').hidden=true;frames[active].focus()};const step=delta=>{const ns=frames.flatMap((_,i)=>api(i)?.footerGroups?.().map(g=>g[0])||Array.from({length:set.items[i].count},(_,j)=>(i===0?1:i===1?14:27)+j));const representative=ns.findLast(n=>n<=current);if(delta>0&&representative===ns.at(-1)){submit(false);return}navigate(ns[Math.max(0,Math.min(ns.length-1,ns.indexOf(representative)+delta))])};$('full-prev').onclick=()=>step(-1);$('full-next').onclick=()=>step(1);
 window.addEventListener('pagehide',()=>{persist();started=false;});
 window.addEventListener('pageshow',()=>{if(set&&ready.size===3&&!done&&!started){started=true;last=Date.now();tick()}});
 document.addEventListener('visibilitychange',()=>{if(started&&!done){tick();persist()}});
 window.addEventListener('message',e=>{if(e.origin!==location.origin)return;const i=frames.findIndex(f=>f.contentWindow===e.source);if(i<0||!e.data)return;
  if(e.data.type==='full-test-error'){fail();return}
  if(e.data.type==='full-test-submit')submit(false);
  if(e.data.type==='full-test-change'&&started)scheduleSave();
  if(e.data.type==='full-test-ready'&&e.data.id===set.items[i].id){if(!ready.has(i)){const doc=frames[i].contentDocument;const sync=e=>{const target=e.target.closest('[data-q]');const n=Number(target?.dataset.q);if(started&&i===active&&n>=1&&n<=40){current=n;paint();persist()}};doc.addEventListener('focusin',sync);doc.addEventListener('click',sync)}ready.add(i);if(ready.size===3&&!started){try{frames.forEach((f,j)=>{if(set.snapshots?.[j])api(j).restore(set.snapshots[j])});clearTimeout(loadTimeout);const savedCurrent=set.current||1;switchPart(set.active||0);current=savedCurrent;started=true;last=Date.now();loading.hidden=true;paint();persist();tick();timer=setInterval(tick,1000)}catch{fail()}}}
 });
 try{const r=await fetch('lesson-catalog.json',{cache:'no-cache'});if(!r.ok)throw Error('catalog');const catalog=await r.json(),draft=C.read(storage,C.key,null);const params=new URLSearchParams(location.search),resume=params.get('resume')==='1',manual=params.get('mode')==='manual';
  if(resume&&draft&&Array.isArray(draft.items)&&draft.items.length===3&&!draft.submitted&&draft.items.every((x,i)=>x.part===i+1&&catalog.some(c=>c.id===x.id))&&Number.isFinite(draft.remainingMs)&&draft.remainingMs>=0&&draft.remainingMs<=3600000)set=draft;
  else set={id:crypto.randomUUID(),items:manual?C.manual(catalog,[params.get('p1'),params.get('p2'),params.get('p3')]):C.select(catalog,storage),remainingMs:3600000,snapshots:[],active:0,current:1};
  set.items.forEach((item,i)=>{const f=document.createElement('iframe');f.title='Part '+(i+1)+' — '+item.title;f.hidden=i!==0;f.src='exam.html?lesson='+encodeURIComponent(item.id)+'&full=1';f.onerror=fail;frames.push(f);$('full-frames').append(f)})
 }catch{fail()}
})();
